/*
 * A039187  Numbers whose base-11 representation has the same number of 3's
 *          and 9's.
 * https://oeis.org/A039187
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) = the n-th smallest non‑negative integer whose base‑11
 *            representation contains an equal number of digits 3 and 9. The
 *            sequence is generated by brute‑force searching natural numbers
 * Range:     u8 n <= 70, u16 n <= 70, u32 n <= 70, u64 n <= 70, u128 n <= 70,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* Helper: test whether a number has the same count of 3's and 9's in base 11 */
static bool balanced_digits(seq_t x)
{
    uint8_t c3 = 0, c9 = 0;
    seq_t t = x;
    while (t > 0) {
        uint8_t d = (uint8_t)(t % 11);
        if (d == 3) c3++;
        else if (d == 9) c9++;
        t /= 11;
    }
    return c3 == c9;
}

seq_t a(idx_t n)
{
    /* static cache of found terms */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;  /* number of elements stored */
    static size_t cache_cap = 0;  /* allocated capacity */
    static seq_t next_candidate = 0;  /* next number to test */

    /* grow cache until it contains at least n terms */
    while (cache_len < (size_t)n) {
        if (balanced_digits(next_candidate)) {
            /* ensure enough capacity */
            if (cache_len >= cache_cap) {
                size_t new_cap = (cache_cap == 0) ? 4 : (cache_cap << 1);
                seq_t *tmp = (seq_t *)realloc(cache, new_cap * sizeof(seq_t));
                if (!tmp) {
                    /* allocation failed – terminate the program safely */
                    abort();
                }
                cache = tmp;
                cache_cap = new_cap;
            }
            cache[cache_len++] = next_candidate;
        }
        next_candidate++;
    }

    return cache[(size_t)n - 1];
}
